[
  {
    "title": "Opposite the Stranger",
    "sceneId": "e5e5dc90-f9ea-5925-a9ea-ce2b71a16809",
    "sourceBlockIds": [
      "e5e5dc90-f9ea-5925-a9ea-ce2b71a16809",
      "3f1f616f-3068-5c3d-b4be-6bda7a462172"
    ],
    "duration": 6,
    "description": "Opening composition: a wide, static-feeling profile two-shot across the narrow aisle of a night train carriage. Ada sits on frame left facing right, and the stranger sits on frame right facing left. His hands are covered by gloves and rest in his lap. Dark windows reflect the carriage lights, and the carriage sways gently. The camera slowly pushes in along the aisle while the stranger shifts and begins to reach toward his inner coat for his ticket. Ending composition: a medium two-shot, still in profile, with the stranger's gloved hand in motion at the centre of the frame. Ada watches him with an unreadable expression.",
    "dialogue": [],
    "characters": [
      { "name": "Ada" },
      { "name": "Stranger" }
    ],
    "atmosphere": "Hushed, enclosed night carriage, rhythmic track noise, low warm interior light against black windows, quiet unease",
    "music": "Sparse low drone, barely present beneath the rhythm of the train"
  },
  {
    "title": "The Crescent Scar",
    "sceneId": "e5e5dc90-f9ea-5925-a9ea-ce2b71a16809",
    "sourceBlockIds": [
      "3f1f616f-3068-5c3d-b4be-6bda7a462172"
    ],
    "duration": 3,
    "description": "Opening composition: a tight insert from slightly above Ada's eyeline, showing the stranger's gloved hand and wrist as he draws out his ticket. As he reaches, the cuff of the glove pulls back and exposes a crescent-shaped scar. The camera makes a slow, subtle drift toward the scar. Ending composition: a close detail of the crescent scar beside the edge of the ticket, with the glove still partly covering his hand.",
    "dialogue": [],
    "characters": [
      { "name": "Stranger" }
    ],
    "atmosphere": "Intimate and charged; the small reveal feels heavy and significant",
    "music": "A single soft, sustained tone enters as the scar appears"
  },
  {
    "title": "Ada Keeps Calm",
    "sceneId": "e5e5dc90-f9ea-5925-a9ea-ce2b71a16809",
    "sourceBlockIds": [
      "3f1f616f-3068-5c3d-b4be-6bda7a462172"
    ],
    "duration": 3,
    "description": "Opening composition: a frontal close-up of Ada, framed over the edge of the stranger's shoulder on frame right. Her eyeline is directed slightly down and to the right, toward his hand. Her eyes register recognition, but her face stays composed and her breathing remains even. She lifts her gaze to meet his. The camera is locked off, with only faint train sway. Ending composition: Ada in close-up, holding steady eye contact just right of the lens.",
    "dialogue": [],
    "characters": [
      { "name": "Ada" },
      { "name": "Stranger" }
    ],
    "atmosphere": "Controlled tension, with stillness masking alarm",
    "music": "The drone holds, restrained"
  },
  {
    "title": "Have We Met?",
    "sceneId": "e5e5dc90-f9ea-5925-a9ea-ce2b71a16809",
    "sourceBlockIds": [
      "e8b1bfe9-af5b-541d-b817-25beacdf5676",
      "4d6b5f69-ad9d-5313-b7cf-22021891d410"
    ],
    "duration": 3,
    "description": "Opening composition: a reverse medium close-up of the stranger over Ada's shoulder on frame left. His eyeline is directed left toward her, and he holds his ticket in his gloved hand. He studies her face and asks his question with mild, probing curiosity. Ending composition: the stranger in medium close-up, waiting for her answer, with his head tilted slightly.",
    "dialogue": [
      { "speaker": "Stranger", "language": "en", "text": "Have we met?" }
    ],
    "characters": [
      { "name": "Stranger" },
      { "name": "Ada" }
    ],
    "atmosphere": "Polite surface over a probing undertone",
    "music": "Near silence; the track rhythm carries the moment"
  },
  {
    "title": "I Would Remember",
    "sceneId": "e5e5dc90-f9ea-5925-a9ea-ce2b71a16809",
    "sourceBlockIds": [
      "4f2c3f13-2a2f-54a4-8dc0-3f1f7bba9cac",
      "3e4c45f4-57a1-5cc1-b3b9-10a957cd3518"
    ],
    "duration": 3,
    "description": "Opening composition: a tighter single on Ada than in the earlier close-up, with no shoulder in frame. She faces right toward the stranger. She answers evenly with a faint, unreadable composure, and her gaze does not waver. The camera is still. Ending composition: Ada in a tight close-up, holding his gaze after the line.",
    "dialogue": [
      { "speaker": "Ada", "language": "en", "text": "I would remember." }
    ],
    "characters": [
      { "name": "Ada" }
    ],
    "atmosphere": "Cool, guarded, double-edged",
    "music": "The drone lowers further, almost gone"
  },
  {
    "title": "Ticket into the Coat",
    "sceneId": "e5e5dc90-f9ea-5925-a9ea-ce2b71a16809",
    "sourceBlockIds": [
      "93236959-ff76-5784-8666-75ff84785ba0"
    ],
    "duration": 4,
    "description": "Opening composition: a medium shot at seat height from the aisle, framing Ada's torso and hands on frame left. Part of the stranger's knee and his gloved hand holding his ticket are visible on frame right. Ada holds her own ticket and, instead of handing it to him, quietly slips it into her coat. The camera eases back slightly to take in both of them. Ending composition: a medium-wide two-shot in profile, matching the opening geography of the scene. Ada's hand rests at her coat, and the two sit opposite each other in silence as the train sways.",
    "dialogue": [],
    "characters": [
      { "name": "Ada" },
      { "name": "Stranger" }
    ],
    "atmosphere": "A quiet act of defiance; the tension is unresolved",
    "music": "A low, unresolved note lingers under the train rhythm"
  }
]

